// Holds the documented BEHAVIOR.md B16 development defaults.
// Centralizes tunables without asserting that proposed hardware pins are verified.
// P0 scaffold compiles this header; behavior and target tests follow their gates.
#pragma once
#include <cstdint>

#ifndef MATCH
#define MATCH 0
#endif
#ifndef MOTORS_ALLOWED
#define MOTORS_ALLOWED 0
#endif
#ifndef SUMOX_B4_STAND
#define SUMOX_B4_STAND 0
#endif
#ifndef SUMOX_P3_DRIVE_TEST
#define SUMOX_P3_DRIVE_TEST 0
#endif
#ifndef SUMOX_P3_TURN_TRIAL
#define SUMOX_P3_TURN_TRIAL 0
#endif
#ifndef SUMOX_P3_STOP_TRIAL
#define SUMOX_P3_STOP_TRIAL 0
#endif
#ifndef SUMOX_P4_REACTIVE
#define SUMOX_P4_REACTIVE 0
#endif
#ifndef SUMOX_TIMING_EVIDENCE
#define SUMOX_TIMING_EVIDENCE 0
#endif
#ifndef SUMOX_P5_ABORT_TIMING
#define SUMOX_P5_ABORT_TIMING 0
#endif
#ifndef SUMOX_MOTOR_FAULT_PROBE
#define SUMOX_MOTOR_FAULT_PROBE 0
#endif
#ifndef SUMOX_B7_BROWNOUT
#define SUMOX_B7_BROWNOUT 0
#endif
static_assert(SUMOX_B7_BROWNOUT == 0 || SUMOX_B7_BROWNOUT == 1,
              "SUMOX_B7_BROWNOUT must be 0 or 1");
static_assert(!SUMOX_B7_BROWNOUT || (!MATCH && !SUMOX_B4_STAND &&
              !SUMOX_P3_DRIVE_TEST && !SUMOX_P3_TURN_TRIAL && !SUMOX_P3_STOP_TRIAL &&
              !SUMOX_P4_REACTIVE && !SUMOX_TIMING_EVIDENCE && !SUMOX_P5_ABORT_TIMING &&
              !SUMOX_MOTOR_FAULT_PROBE), "B7 brownout is exclusive and not a MATCH build");
// D169 selects an inert diagnostic build; it grants no upload or motor permission.
static_assert(SUMOX_MOTOR_FAULT_PROBE == 0 || SUMOX_MOTOR_FAULT_PROBE == 1,
              "SUMOX_MOTOR_FAULT_PROBE must be 0 or 1");
static_assert(!SUMOX_MOTOR_FAULT_PROBE || (!MATCH && !MOTORS_ALLOWED &&
              !SUMOX_B4_STAND && !SUMOX_P3_DRIVE_TEST && !SUMOX_P3_TURN_TRIAL &&
              !SUMOX_P3_STOP_TRIAL && !SUMOX_P4_REACTIVE && !SUMOX_TIMING_EVIDENCE &&
              !SUMOX_P5_ABORT_TIMING),
              "Motor fault probe is exclusive and requires inert flags");
static_assert(SUMOX_P5_ABORT_TIMING == 0 || SUMOX_P5_ABORT_TIMING == 1,
              "SUMOX_P5_ABORT_TIMING must be 0 or 1");
static_assert(!SUMOX_P5_ABORT_TIMING || (!MATCH && !SUMOX_B4_STAND &&
              !SUMOX_P3_DRIVE_TEST && !SUMOX_P3_TURN_TRIAL && !SUMOX_P3_STOP_TRIAL &&
              !SUMOX_P4_REACTIVE && !SUMOX_TIMING_EVIDENCE),
              "P5 abort timing is exclusive and not a MATCH build");
static_assert(SUMOX_TIMING_EVIDENCE == 0 || SUMOX_TIMING_EVIDENCE == 1,
              "SUMOX_TIMING_EVIDENCE must be 0 or 1");
static_assert(!SUMOX_TIMING_EVIDENCE || SUMOX_P4_REACTIVE,
              "Timing evidence requires the P4 reactive profile");
static_assert(MATCH == 0 || MATCH == 1, "MATCH must be 0 or 1");
static_assert(MOTORS_ALLOWED == 0 || MOTORS_ALLOWED == 1, "MOTORS_ALLOWED must be 0 or 1");
static_assert(SUMOX_B4_STAND == 0 || SUMOX_B4_STAND == 1, "SUMOX_B4_STAND must be 0 or 1");
static_assert(!SUMOX_B4_STAND || !MATCH, "B4 stand profile is not a MATCH build");
static_assert(SUMOX_P3_DRIVE_TEST == 0 || SUMOX_P3_DRIVE_TEST == 1,
              "SUMOX_P3_DRIVE_TEST must be 0 or 1");
static_assert(!SUMOX_P3_DRIVE_TEST || (!MATCH && !SUMOX_B4_STAND),
              "P3 drive profile is exclusive and not a MATCH build");
static_assert(SUMOX_P3_TURN_TRIAL == 0 || SUMOX_P3_TURN_TRIAL == 1,
              "SUMOX_P3_TURN_TRIAL must be 0 or 1");
static_assert(!SUMOX_P3_TURN_TRIAL || (!MATCH && !SUMOX_B4_STAND && !SUMOX_P3_DRIVE_TEST),
              "P3 turn trial is exclusive and not a MATCH build");
static_assert(SUMOX_P3_STOP_TRIAL == 0 || SUMOX_P3_STOP_TRIAL == 1,
              "SUMOX_P3_STOP_TRIAL must be 0 or 1");
static_assert(!SUMOX_P3_STOP_TRIAL || (!MATCH && !SUMOX_B4_STAND &&
              !SUMOX_P3_DRIVE_TEST && !SUMOX_P3_TURN_TRIAL),
              "P3 stopping trial is exclusive and not a MATCH build");
static_assert(SUMOX_P4_REACTIVE == 0 || SUMOX_P4_REACTIVE == 1,
              "SUMOX_P4_REACTIVE must be 0 or 1");
static_assert(!SUMOX_P4_REACTIVE || (!MATCH && !SUMOX_B4_STAND &&
              !SUMOX_P3_DRIVE_TEST && !SUMOX_P3_TURN_TRIAL && !SUMOX_P3_STOP_TRIAL),
              "P4 reactive profile is exclusive and not a MATCH build");

